    releaseKeys();audioRecordMode=false;recording=false;project=emptyProject();project.bpm=120;selectedTrack=7;selectedNotes.clear();selectedNote=-1;undoStack.clear();redoStack.clear();currentFile=File();typingEnabled=true;typingVelocity=102;typingSustain=false;typingCapture.clear();typingCaptureContext=typingContext();publish();engine->prepare(48000);AudioBuffer<float> block(2,1024);getNextAudioBlock(AudioSourceChannelInfo(&block,0,1024));
    auto rev=revision;perform(typingVelocitySet,32);perform(typingOctaveSet,5);check(typingVelocity==32&&octave==5&&revision==rev&&undoStack.empty(),"typing velocity and octave preferences do not dirty the project or add undo");TypingSettings settings;check(loadTypingSettings(root.getChildFile("data/typing-keyboard.json"),settings).wasOk()&&settings.velocity==32&&settings.octave==5&&settings.enabled,"typing preferences use the native local save path");
