    auto before=JSON::toString(projectToJson(project));history=undoStack.size();recording=true;check(!recallTypingPhrase(now)&&JSON::toString(projectToJson(project))==before&&undoStack.size()==history,"recording blocks retrospective capture atomically");recording=false;
